from typing import List


class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        nums.sort()
        count = 0
        prev = float("-inf")
        for x in nums:
            candidate = max(prev + 1, x - k)
            if candidate <= x + k:
                count += 1
                prev = candidate
        return count

